<?php
/** Private-key-gated two-step setup. Administrator autofill cannot replace the verified key. */
require_once __DIR__.'/includes/installer_security.php';
hosting_bootstrap_guard();
ini_set('display_errors','0');header('Cache-Control: no-store');header('X-Frame-Options: DENY');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header("Content-Security-Policy: default-src 'self'; style-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
$https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||((getenv('NIKXOR_TRUST_PROXY')==='1')&&($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https');
if(!$https&&getenv('NIKXOR_ALLOW_LOCAL_INSTALL')!=='1'){http_response_code(403);exit('Installation requires HTTPS.');}
