session_name('NIKXOR_INSTALL');ini_set('session.use_strict_mode','1');ini_set('session.use_only_cookies','1');ini_set('session.use_trans_sid','0');if(hosting_profile())hosting_validate_native_session();else session_save_path($installRuntimeDir);session_set_cookie_params(['secure'=>$https,'httponly'=>true,'samesite'=>'Strict','path'=>'/']);if(!session_start()){http_response_code(503);exit('Installation session unavailable.');}
$lang=($_GET['lang']??$_SESSION['install_lang']??'da')==='en'?'en':'da';$_SESSION['install_lang']=$lang;
function it($en,$da){return $GLOBALS['lang']==='en'?$en:$da;}function ih($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function iv(string $key,string $default=''): string {return ih($GLOBALS['values'][$key]??$default);}
$_SESSION['install_csrf']??=bin2hex(random_bytes(32));$error='';$done=false;$existingAccounts=false;$preflightError=false;
$hasConfig=is_file($installRuntimeDir.'/database.php')||getenv('DB_NAME')||getenv('NIKXOR_DB_DRIVER');$tokenFile=$installRuntimeDir.'/install-token.key';
$values=[];foreach(['db_host'=>253,'db_port'=>5,'db_name'=>64,'db_user'=>128,'app_url'=>2048,'username'=>50] as $field=>$max)if(is_string($_POST[$field]??null)&&strlen($_POST[$field])<=$max)$values[$field]=trim($_POST[$field]);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 $lock=fopen($installRuntimeDir.'/installation.lock','c');if(!$lock||!flock($lock,LOCK_EX)){http_response_code(503);exit('Installation lock unavailable.');}
 try{
  if(is_file($installRuntimeDir.'/installed.lock'))throw new RuntimeException(it('Installation is already locked.','نصب از قبل قفل شده است.'));
  if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['install_csrf'],$_POST['csrf']))throw new RuntimeException(it('Refresh this form and try again.','صفحه را تازه کنید و دوباره کوشش کنید.'));
  $rate=$installRuntimeDir.'/install-attempts-'.hash('sha256',($_SERVER['REMOTE_ADDR']??'local').'|'.intdiv(time(),600)).'.json';$attempts=is_file($rate)?(int)file_get_contents($rate):0;file_put_contents($rate,(string)($attempts+1),LOCK_EX);chmod($rate,0600);if($attempts>=10)throw new RuntimeException(it('Too many attempts. Try later.','تلاش‌ها بیشتر از حد مجاز است؛ بعداً کوشش کنید.'));
