  if($action==='verify_key'){
   if(!installer_key_matches($_POST['install_token']??null))throw new RuntimeException(it('The private installation key does not match. Use the 64-character key from the same installation package.','کلید خصوصی نصب مطابقت ندارد؛ کلید ۶۴ حرفی همان بستهٔ نصب را وارد کنید.'));
   session_regenerate_id(true);$_SESSION['install_key_verified_at']=time();$_SESSION['install_key_binding']=installer_authorization_binding();$_SESSION['install_csrf']=bin2hex(random_bytes(32));
   header('Location: '.hosting_url('install.php').'?lang='.$lang,true,303);exit;
  }
