  if(!$hasConfig){
    $host=trim((string)($_POST['db_host']??''));$port=(string)($_POST['db_port']??'3306');$db=trim((string)($_POST['db_name']??''));$user=trim((string)($_POST['db_user']??''));$pass=(string)($_POST['db_password']??'');
    if(!preg_match('/^[a-zA-Z0-9_.:-]{1,253}$/D',$host)||!ctype_digit($port)||(int)$port<1||(int)$port>65535||!preg_match('/^[a-zA-Z0-9_]{1,64}$/D',$db)||$user==='')throw new InvalidArgumentException(it('Check database fields.','خانه‌های دیتابیس را بررسی کنید.'));
    try{$probe=new PDO('mysql:host='.$host.';port='.$port.';dbname='.$db.';charset=utf8mb4',$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}catch(Throwable $e){throw new RuntimeException(it('Database connection failed. Check the host and credentials.','اتصال دیتابیس ناکام شد؛ مشخصات هاست و حساب را بررسی کنید.'));}
