    $h=fopen($installRuntimeDir.'/database.php','x');if(!$h)throw new RuntimeException('Configuration already exists.');chmod($installRuntimeDir.'/database.php',0600);$bytes=hosting_php_guard().'return '.var_export(['HOST'=>$host,'PORT'=>$port,'NAME'=>$db,'USER'=>$user,'PASS'=>$pass],true).';';if(fwrite($h,$bytes)!==strlen($bytes)){fclose($h);unlink($installRuntimeDir.'/database.php');throw new RuntimeException('Configuration could not be saved.');}fclose($h);
  }
