  require_once __DIR__.'/includes/management_service.php';
  $q=$pdo->query('SELECT COUNT(*) FROM users');$count=(int)$q->fetchColumn();$q->closeCursor();if($count!==0)throw new RuntimeException(it('Existing accounts detected. Use authenticated setup after signing in; installation will not replace them.','حساب موجود یافت شد؛ پس از ورود از بخش راه‌اندازی استفاده کنید. نصب، حساب‌ها را جایگزین نمی‌کند.'));
  $publicUrl=invoice_public_origin(is_string($_POST['app_url']??null)?$_POST['app_url']:'');if(!$publicUrl)throw new InvalidArgumentException(it('Enter the HTTPS website address for invoice verification.','آدرس HTTPS ویب‌سایت را برای تأیید بل وارد کنید.'));
  $username=trim((string)($_POST['username']??''));if(!preg_match('/^[a-zA-Z0-9_.@-]{3,50}$/D',$username))throw new InvalidArgumentException(it('Use a valid administrator username.','نام معتبر برای حساب مدیر بنویسید.'));security_validate_new_password($_POST['password']??'',$_POST['confirm_password']??'');
  $secret=strtoupper(str_replace(' ','',(string)($_POST['totp_secret']??'')));totp_decode($secret);$code=(string)($_POST['totp_code']??'');$valid=false;foreach([-1,0,1] as $offset)if(hash_equals(totp_code($secret,intdiv(time(),30)+$offset),$code))$valid=true;if(!$valid)throw new InvalidArgumentException(it('Verify your authenticator code before creating the administrator.','پیش از ساخت مدیر، کُد برنامهٔ تأییدکننده را درست بنویسید.'));
  runtime_save(['NIKXOR_PUBLIC_URL'=>$publicUrl]);
  $pdo->beginTransaction();try{$pdo->prepare("INSERT INTO users (username,password,fullname,role,status,shop_id) VALUES (?,?,?,'superadmin','active',NULL)")->execute([$username,password_hash($_POST['password'],PASSWORD_DEFAULT),'Ahmad Najeem Nik']);$id=(int)$pdo->lastInsertId();access_ensure_profile($id);$totpPath=security_private_dir().'/totp-'.$id.'.key';if(hosting_profile())hosting_write_secret($totpPath.'.php',$secret);else{$h=fopen($totpPath,'x');if(!$h)throw new RuntimeException('Second factor already exists.');chmod($totpPath,0600);fwrite($h,$secret);fclose($h);}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
  $h=fopen($installRuntimeDir.'/installed.lock','x');if(!$h)throw new RuntimeException('Could not seal installation.');chmod($installRuntimeDir.'/installed.lock',0600);fwrite($h,gmdate('c'));fclose($h);if(is_file($tokenFile))unlink($tokenFile);$done=true;$_SESSION=[];session_destroy();
